import React, { useState, useEffect } from "react"
import { collection, addDoc, Timestamp, onSnapshot, doc } from "firebase/firestore"
import { db } from "../firebase/config"
import PortalLayout from "../components/portal/PortalLayout"

interface ServiceItem {
  id: string
  label: string
  isActive: boolean
  order: number
}

interface BusinessInfo {
  name: string
  phone: string
  email: string
}

type TimeOfDay = "morning" | "afternoon" | "any"

interface FormState {
  clientName: string
  phone: string
  email: string
  serviceType: string
  customDescription: string
  notes: string
  dates: [string, string, string]
  preferredTimeOfDay: TimeOfDay
}

interface FormErrors {
  clientName?: string
  phone?: string
  email?: string
  serviceType?: string
  customDescription?: string
  dates?: string
}

const EMPTY: FormState = {
  clientName: "",
  phone: "",
  email: "",
  serviceType: "",
  customDescription: "",
  notes: "",
  dates: ["", "", ""],
  preferredTimeOfDay: "any",
}

function today() {
  return new Date().toISOString().slice(0, 10)
}

function validate(f: FormState): FormErrors {
  const errors: FormErrors = {}
  if (!f.clientName.trim() || f.clientName.trim().length < 2)
    errors.clientName = "Name must be at least 2 characters"
  if (!f.phone.trim() || !/^[\d\s\-()+]+$/.test(f.phone.trim()))
    errors.phone = "Enter a valid phone number"
  if (f.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email.trim()))
    errors.email = "Enter a valid email address"
  if (!f.serviceType)
    errors.serviceType = "Please select a service"
  if (f.serviceType === "custom" && !f.customDescription.trim())
    errors.customDescription = "Please describe the service needed"
  if (!f.dates[0])
    errors.dates = "At least one preferred date is required"
  else if (f.dates[0] < today())
    errors.dates = "Preferred date cannot be in the past"
  return errors
}

export default function RequestPage() {
  const [services, setServices] = useState<ServiceItem[]>([])
  const [business, setBusiness] = useState<BusinessInfo>({ name: "Garage Carlos Inc.", phone: "", email: "" })
  const [form, setForm] = useState<FormState>(EMPTY)
  const [errors, setErrors] = useState<FormErrors>({})
  const [submitting, setSubmitting] = useState(false)
  const [submitted, setSubmitted] = useState(false)

  useEffect(() => {
    if (!db) return
    const unsubServices = onSnapshot(doc(db, "settings", "services"), snap => {
      const list = (snap.data()?.list as ServiceItem[]) ?? []
      setServices(list.filter(s => s.isActive).sort((a, b) => a.order - b.order))
    })
    const unsubBusiness = onSnapshot(doc(db, "settings", "business"), snap => {
      const d = snap.data()
      if (d) setBusiness({ name: d.name ?? "Auto Service", phone: d.phone ?? "", email: d.email ?? "" })
    })
    return () => { unsubServices(); unsubBusiness() }
  }, [])

  function set<K extends keyof FormState>(key: K, value: FormState[K]) {
    setForm(prev => ({ ...prev, [key]: value }))
    setErrors(prev => ({ ...prev, [key]: undefined }))
  }

  function setDate(idx: 0 | 1 | 2, value: string) {
    const next: [string, string, string] = [...form.dates] as [string, string, string]
    next[idx] = value
    setForm(prev => ({ ...prev, dates: next }))
    if (idx === 0) setErrors(prev => ({ ...prev, dates: undefined }))
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    const errs = validate(form)
    setErrors(errs)
    if (Object.keys(errs).length > 0) return

    setSubmitting(true)
    try {
      const preferredDates = form.dates.filter(Boolean)
      await addDoc(collection(db!, "appointmentRequests"), {
        clientName: form.clientName.trim(),
        phone: form.phone.trim(),
        email: form.email.trim(),
        existingClientId: null,
        serviceType: form.serviceType,
        customDescription: form.serviceType === "custom" ? form.customDescription.trim() : "",
        notes: form.notes.trim(),
        preferredDates,
        preferredTimeOfDay: form.preferredTimeOfDay,
        status: "pending",
        createdAt: Timestamp.now(),
        reviewedAt: null,
        reviewedBy: null,
      })
      setSubmitted(true)
    } catch {
      setErrors({ clientName: "Something went wrong. Please try again." })
    } finally {
      setSubmitting(false)
    }
  }

  if (submitted) {
    return (
      <PortalLayout shopName={business.name} shopPhone={business.phone} shopEmail={business.email}>
        <div className="flex flex-col items-center justify-center py-20 text-center gap-5">
          <span className="text-5xl">✅</span>
          <div>
            <h1 className="text-xl font-bold text-gray-800 mb-2">Request submitted!</h1>
            <p className="text-gray-500 text-sm max-w-xs mx-auto">
              We'll review your request and contact you shortly to confirm your appointment.
            </p>
          </div>
          <button
            onClick={() => { setForm(EMPTY); setSubmitted(false) }}
            className="text-sm text-blue-600 hover:text-blue-700 font-medium transition-colors"
          >
            Submit another request
          </button>
        </div>
      </PortalLayout>
    )
  }

  const inputCls = (err?: string) =>
    `w-full border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${
      err ? "border-red-400" : "border-gray-300"
    }`

  return (
    <PortalLayout shopName={business.name} shopPhone={business.phone} shopEmail={business.email}>
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Request an Appointment</h1>
        <p className="text-sm text-gray-500 mt-1">
          Fill out the form below and we'll get back to you to confirm.
        </p>
      </div>

      <form onSubmit={handleSubmit} noValidate className="space-y-5">
        {/* Contact */}
        <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-4">
          <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Your Info</h2>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Full Name <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              value={form.clientName}
              onChange={e => set("clientName", e.target.value)}
              className={inputCls(errors.clientName)}
              placeholder="Jean-Pierre Tremblay"
            />
            {errors.clientName && <p className="text-xs text-red-500 mt-0.5">{errors.clientName}</p>}
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Phone <span className="text-red-500">*</span>
            </label>
            <input
              type="tel"
              value={form.phone}
              onChange={e => set("phone", e.target.value)}
              className={inputCls(errors.phone)}
              placeholder="514-555-0100"
            />
            {errors.phone && <p className="text-xs text-red-500 mt-0.5">{errors.phone}</p>}
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Email <span className="text-xs font-normal text-gray-400 ml-1">— optional, for appointment confirmation</span>
            </label>
            <input
              type="email"
              value={form.email}
              onChange={e => set("email", e.target.value)}
              className={inputCls(errors.email)}
              placeholder="you@example.com"
            />
            {errors.email && <p className="text-xs text-red-500 mt-0.5">{errors.email}</p>}
          </div>
        </div>

        {/* Service */}
        <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-4">
          <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Service</h2>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Service needed <span className="text-red-500">*</span>
            </label>
            <select
              value={form.serviceType}
              onChange={e => set("serviceType", e.target.value)}
              className={inputCls(errors.serviceType) + " bg-white"}
            >
              <option value="">Select a service…</option>
              {services.map(s => (
                <option key={s.id} value={s.id}>{s.label}</option>
              ))}
              <option value="custom">Other / Custom</option>
            </select>
            {errors.serviceType && <p className="text-xs text-red-500 mt-0.5">{errors.serviceType}</p>}
          </div>

          {form.serviceType === "custom" && (
            <div>
              <label className="block text-xs font-medium text-gray-700 mb-1">
                Describe the service <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={form.customDescription}
                onChange={e => set("customDescription", e.target.value)}
                className={inputCls(errors.customDescription)}
                placeholder="e.g. AC recharge, suspension check…"
              />
              {errors.customDescription && <p className="text-xs text-red-500 mt-0.5">{errors.customDescription}</p>}
            </div>
          )}

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Additional notes</label>
            <textarea
              value={form.notes}
              onChange={e => set("notes", e.target.value)}
              rows={3}
              maxLength={500}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              placeholder="Any details we should know about your vehicle or the issue…"
            />
            <p className="text-xs text-gray-400 text-right mt-0.5">{form.notes.length}/500</p>
          </div>
        </div>

        {/* Dates */}
        <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-4">
          <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Preferred Dates</h2>
          <p className="text-xs text-gray-400 -mt-2">You can suggest up to 3 dates. We'll confirm one with you.</p>

          {([0, 1, 2] as const).map(idx => (
            <div key={idx}>
              <label className="block text-xs font-medium text-gray-700 mb-1">
                {idx === 0 ? <>First choice <span className="text-red-500">*</span></> : `Option ${idx + 1}`}
                {idx > 0 && <span className="text-gray-400 font-normal ml-1">— optional</span>}
              </label>
              <input
                type="date"
                value={form.dates[idx]}
                min={today()}
                onChange={e => setDate(idx, e.target.value)}
                className={inputCls(idx === 0 ? errors.dates : undefined)}
              />
              {idx === 0 && errors.dates && <p className="text-xs text-red-500 mt-0.5">{errors.dates}</p>}
            </div>
          ))}

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-2">Preferred time of day</label>
            <div className="flex gap-3 flex-wrap">
              {(
                [
                  { value: "morning", label: "🌅 Morning" },
                  { value: "afternoon", label: "☀️ Afternoon" },
                  { value: "any", label: "🕐 No preference" },
                ] as { value: TimeOfDay; label: string }[]
              ).map(opt => (
                <label key={opt.value} className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="radio"
                    name="timeOfDay"
                    value={opt.value}
                    checked={form.preferredTimeOfDay === opt.value}
                    onChange={() => set("preferredTimeOfDay", opt.value)}
                    className="accent-blue-600"
                  />
                  <span className="text-sm text-gray-700">{opt.label}</span>
                </label>
              ))}
            </div>
          </div>
        </div>

        <button
          type="submit"
          disabled={submitting}
          className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl text-sm transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
        >
          {submitting ? (
            <>
              <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
              Submitting…
            </>
          ) : "Submit Request"}
        </button>
      </form>
    </PortalLayout>
  )
}
